on conflict (pack_id, card_id) do update set
  pull_probability = excluded.pull_probability,
  source_note = excluded.source_note,
  verified_at = excluded.verified_at,
  updated_at = now();

-- Stop and roll back if the catalog, pack, or generated odds are incomplete.
do $$
declare
  fantastical_parade_cards integer;
  fantastical_parade_packs integer;
  fantastical_parade_odds integer;
begin
  select count(*)
  into fantastical_parade_cards
  from public.cards
  where set_id = 'B2';

  select count(*)
  into fantastical_parade_packs
  from public.packs
  where set_id = 'B2';

  select count(*)
  into fantastical_parade_odds
  from public.card_pack_odds
  where pack_id = 'b2-fantastical-parade';

  if fantastical_parade_cards <> 234 then
    raise exception
      'Expected 234 Fantastical Parade cards, found %',
      fantastical_parade_cards;
  end if;

  if fantastical_parade_packs <> 1 then
    raise exception
      'Expected 1 Fantastical Parade pack, found %',
      fantastical_parade_packs;
  end if;

  if fantastical_parade_odds <> 234 then
    raise exception
      'Expected 234 Fantastical Parade odds rows, found %',
      fantastical_parade_odds;
  end if;
end
$$;

commit;

-- Expected: 234 total records for the Fantastical Parade pack.
select
  cards.rarity,
  count(*) as cards,
  min(card_pack_odds.pull_probability) as min_pull_probability,
  max(card_pack_odds.pull_probability) as max_pull_probability
from public.card_pack_odds
join public.cards
  on cards.id = card_pack_odds.card_id
where card_pack_odds.pack_id = 'b2-fantastical-parade'
group by cards.rarity
order by min(cards.collector_number);
